using System; using System.Reflection; using System.Collections; using Por.Core;
public static class TableChecks {
 static void ProbeSet(string name,string expected) {count++;var set=typeof(GDConsts).GetField(name).GetValue(null) as System.Collections.Generic.ISet<char>;if(set==null||set.Count!=expected.Length){failed++;Console.WriteLine(name+": set shape");return;}foreach(char ch in expected)if(!set.Contains(ch)){failed++;Console.WriteLine(name+": missing set member "+ch);}}
 static void ValidateLeafType(object value,string s){Type t=null;switch(s.ToLowerInvariant()){case "byte":t=typeof(byte);break;case "shortint":t=typeof(sbyte);break;case "word":t=typeof(ushort);break;case "integer":t=typeof(short);break;case "longint":t=typeof(int);break;case "boolean":t=typeof(bool);break;case "char":t=typeof(char);break;}if(s.StartsWith("string",StringComparison.OrdinalIgnoreCase)||s.StartsWith("TStr")||s=="TName15"||s=="TPathStr")t=typeof(string);if(t!=null&&(value==null||value.GetType()!=t))throw new Exception("source width "+s+" got "+(value==null?"null":value.GetType().ToString()));}
 static int count, failed;
 static object Member(object obj,string name) {var t=obj.GetType();var f=t.GetField(name);return f!=null?f.GetValue(obj):t.GetProperty(name).GetValue(obj,null);}
 static void Probe(string name,object[] path,string expected,string sourceType) {count++;try {object obj=typeof(GDConsts).GetField(name).GetValue(null);foreach(object step in path){if(step is string)obj=Member(obj,(string)step);else{var ix=(int[])step; if(obj is Array)obj=((Array)obj).GetValue(ix);else {var vals=new object[ix.Length];for(int i=0;i<ix.Length;i++)vals[i]=ix[i];obj=obj.GetType().GetProperty("Item").GetValue(obj,vals);}}}ValidateLeafType(obj,sourceType);string actual=Convert.ToString(obj,System.Globalization.CultureInfo.InvariantCulture);if(actual!=expected)throw new Exception("expected "+expected+" actual "+actual);}catch(Exception ex){failed++;Console.WriteLine("TABLEFAIL "+System.Text.Json.JsonSerializer.Serialize(new {name=name,path=path,expected=expected,error=ex.Message}));}}
 public static void Run(){

